STRATEGY_REGISTRY = ATOMIC_STRATEGY_REGISTRY

def get_strategy(strategy_id: str) -> Dict[str, Any] | None:
    for item in ATOMIC_STRATEGY_REGISTRY:
        if item.get('atomic_strategy_id') == strategy_id:
            return item
    return None

def get_trader_seed(strategy_id: str) -> Dict[str, Any] | None:
    for item in TRADER_SEED_REGISTRY:
        if item.get('strategy_id') == strategy_id:
            return item
    return None

def strategies_by_family(family: str) -> List[Dict[str, Any]]:
    key = str(family).strip().lower()
    return [x for x in ATOMIC_STRATEGY_REGISTRY if str(x.get('family','')).strip().lower() == key]

def strategies_by_tag(tag: str) -> List[Dict[str, Any]]:
    key = str(tag).strip().lower()
    return [x for x in ATOMIC_STRATEGY_REGISTRY if key in {str(t).strip().lower() for t in x.get('mechanism_tags', [])}]

def research_variants() -> List[Dict[str, Any]]:
    return [x for x in ATOMIC_STRATEGY_REGISTRY if x.get('rule_precision') == 'research_variant']

def untested() -> List[Dict[str, Any]]:
    return [x for x in ATOMIC_STRATEGY_REGISTRY if x.get('validation_status') == 'UNTESTED']

def validate_registry() -> Dict[str, Any]:
    ids = [x.get('atomic_strategy_id') for x in ATOMIC_STRATEGY_REGISTRY]
    hashes = [x.get('strategy_dna_hash') for x in ATOMIC_STRATEGY_REGISTRY]
    duplicate_ids = sorted({x for x in ids if ids.count(x) > 1})
    duplicate_hashes = sorted({x for x in hashes if hashes.count(x) > 1})
    missing_hash = [x.get('atomic_strategy_id') for x in ATOMIC_STRATEGY_REGISTRY if not x.get('strategy_dna_hash')]
    invalid_claims = [x.get('atomic_strategy_id') for x in ATOMIC_STRATEGY_REGISTRY if x.get('claimed_performance') is not None and x.get('evidence_grade') == 'D']
    return {'registry_version': REGISTRY_VERSION, 'seed_count': len(TRADER_SEED_REGISTRY), 'atomic_count': len(ATOMIC_STRATEGY_REGISTRY), 'duplicate_ids': duplicate_ids, 'duplicate_hashes': duplicate_hashes, 'missing_hash': missing_hash, 'claim_evidence_conflicts': invalid_claims, 'ok': not duplicate_ids and not duplicate_hashes and not missing_hash and not invalid_claims}

def registry_sha256() -> str:
    payload = repr((TRADER_SEED_REGISTRY, ATOMIC_STRATEGY_REGISTRY)).encode('utf-8')
    return hashlib.sha256(payload).hexdigest()

if __name__ == '__main__':
    report = validate_registry()
    print('GSR registry:', REGISTRY_VERSION)
    print('Trader seeds:', report['seed_count'])
    print('Atomic strategies:', report['atomic_count'])
    print('Validation:', 'PASS' if report['ok'] else 'FAIL')
    print('Registry SHA256:', registry_sha256())
